// GameManager.OnSceneLoaded() — 전투 씬 1
gameContext.SetEnemyType(enemyType);
sceneBinder.BindSceneObjects(gameContext);

// SceneBinder.BindSceneObjectsWithEnvironment()
player.Hp = gameContext.ShipHp;
player.SetReactorPower(gameContext.ShipPower);
player.SetFacilitySystems(gameContext.FacilityStates);
player.SetCrewsState(gameContext.CrewStates);
player.SetWeaponTypes(gameContext.WeaponTypes);
BindCombatSystem(player, enemy);

// ShipPowerController.AllocatePower — 핵심 부분
int currentPower = GetAssignedPower(facilityType);
int nextPower = currentPower + amount;
if (CanSpendReactorPower(amount) == false ||
facility.CanAddPower(amount) == false ||
CanSetFacilityPower(facility, nextPower) == false)
{
return;
}

SetAssignedPower(facilityType, nextPower);
facility.AddPower(amount);
reactorController.ReducePower(amount);

// FacilityController.UpdateFacilityStatus — 최종 코드
if (TotalDamage == MaxPowerLimit)
facilityStatus = FacilityStatus.Broked;
else if (TotalDamage > 0 && TotalDamage < MaxPowerLimit)
facilityStatus = FacilityStatus.Damaged;
else if (Power == 0)
facilityStatus = FacilityStatus.Disabled;
else if (TotalDamage == 0)
facilityStatus = FacilityStatus.Normal;

// EnemyController.Start()
targetingSystem = new RandomTargeter(
CombatSystem.Instance.GetPlayerRooms()
);

// CombatSystem.GetPlayerRooms()
public List<Room> GetPlayerRooms()
{
return ships[0].Rooms;
}

// ShipController
protected virtual void Start()
{
crewSystem.Rooms = Rooms;
}

// SceneBinder.BindSceneObjectsWithEnvironment()
PlayerController player = FindFirstObjectByType<PlayerController>();
EnemyController enemy = SpawnEnemyOrFindSceneEnemy(gameContext.EnemyType);
BindCombatSystem(player, enemy);   // → CombatSystem.Instance.InitCombatSystem(player, enemy)

// CombatSystem.InitCombatSystem()
Collider2D playerCollider = playerOwnership.GetComponent<Collider2D>();
Collider2D enemyCollider = enemyOwnership.GetComponent<Collider2D>();
ships = new ShipController[] { player, enemy };
shipAreas = new[] { playerCollider, enemyCollider };

TargetRoom = room;
CurrentRoom.ReduceCrew(this);

if (CurrentRoom.IsEmptyCrew())
{
AssistFacility(false);
ResetRepairProgressOnEmptyRoom(CurrentRoom);
}

TargetRoom.AddCrew(this);
CurrentRoom = TargetRoom;
crewStatus = CrewStatus.Moving;

// CrewSystem.HandleCrewDeath — 핵심 부분
ship.Crews.Remove(crew);
crews.Remove(crew);

// 승무원이 속한 Room을 검색
room.ReduceCrew(crew);

// EnemyController.Start()
targetingSystem = new RandomTargeter(CombatSystem.Instance.GetPlayerRooms());
WeaponController.SetWeaponsTargetingSystem(targetingSystem);

// WeaponSystem.SetWeaponsTargetingSystem()
TargetingSystem = targetingSystem;
for (int i = 0; i < weapons.Count; i++)
{
weapons[i].SetTargetingSystem(TargetingSystem);
}

// ProjectileController.OnTriggerEnter2D() — 실드에 부딪힐 때
if (canHitShield)
{
bool isShielded = CombatSystem.Instance.HandleShieldCollision(this);
if (isShielded)
{
Destroy(gameObject);
}
}

// ProjectileController.Update() — 목표 방에 닿을 때
if (IsArrived)
{
CombatSystem.Instance.HandleRoomCollision(this);
// … 폭발 효과 위치 지정
Destroy(gameObject);
}

// CombatSystem.HandleShieldCollision() — 도착 순간의 실드 수로 판정
if (oppenentShieldController.ShieldCount > 0)
{
oppenentShieldController.TakeDamageToShield(projectile.ShieldDamage);
return true;
}

// ShipController.CheckGameOver()
bool isGameOver = IsDead || crewSystem.IsAllCrewDead;
if (!isGameOver || isDeadCoroutineActivated)
{
return;
}
// … 결과 판정
StartCoroutine(DeadCoroutine(deadAnimationTime, battleResult));

// ShipController.DeadCoroutine()
isDeadCoroutineActivated = true;
yield return new WaitForSeconds(seconds);
GameManager.Instance.HandleBattleResult(result);

// CombatSystem.MoveToEnemyArea()
Vector3 spawnPos = GetRandomPositionOnColliderEdge(nextShipCol, projectile.transform.position.z, seed);
Vector3 targetPos = projectile.TargetPos;

projectile.transform.position = spawnPos;
Vector3 direction = targetPos - spawnPos;
direction.z = projectile.transform.position.z;
projectile.transform.right = direction;

// WeaponSystem.ResetSelectedWeapon()
ResetWeaponTargetSprite(selectedWeapon);
CursorController.Instance.ResetMouseSprite();
// … selectedWeapon이 없으면 종료
selectedWeapon.SetRoomTarget(emptyData);
selectedWeapon = null;

// PlayerController.Update()
if (SimpleInput.GetKeyDown(Key.Escape))
{
WeaponController.ResetSelectedWeapon();
crewSystem.ResetSelectedCrews();
}

if (!CanControlShip())
{
return;
}
